`default_nettype none

// Programmable protocol emulator: a tiny cycle-exact CPU running firmware from ROM.
//   Input pins  0-7  = ui_in[7:0]
//   Input pins  8-15 = uio_in[7:0]
//   Output pins 0-7  = uo_out[7:0]
// The firmware in rom.v is generated by tools/asm.py from firmware/*.asm.
module tt_um_atlasmountainz_protocol_emulator (
    input  wire [7:0] ui_in,    // Dedicated inputs
    output wire [7:0] uo_out,   // Dedicated outputs
    input  wire [7:0] uio_in,   // IOs: Input path
    output wire [7:0] uio_out,  // IOs: Output path
    output wire [7:0] uio_oe,   // IOs: Enable path (active high: 0=input, 1=output)
    input  wire       ena,      // always 1 when the design is powered, so you can ignore it
    input  wire       clk,      // clock
    input  wire       rst_n     // reset_n - low to reset
);

  // Two-flop synchroniser: the pins are asynchronous to the core clock.
  reg [15:0] sync1, sync2;
  always @(posedge clk) begin
    if (!rst_n) begin
      sync1 <= 16'd0;
      sync2 <= 16'd0;
    end else begin
      sync1 <= {uio_in, ui_in};
      sync2 <= sync1;
    end
  end

  wire [6:0]  rom_addr;
  wire [15:0] rom_data;

  cpu u_cpu (
      .clk     (clk),
      .rst_n   (rst_n),
      .pins_in (sync2),
      .pins_out(uo_out),
      .rom_addr(rom_addr),
      .rom_data(rom_data)
  );

  rom u_rom (
      .addr(rom_addr),
      .data(rom_data)
  );

  assign uio_out = 8'b0;
  assign uio_oe  = 8'b0;

  // List all unused inputs to prevent warnings
  wire _unused = &{ena, 1'b0};

endmodule
